local Profiles=include("rhenium_loadout_profiles/profiles.lua");local Server={HookPrefix="RheniumLoadoutProfiles"};local profiles,players,installed=nil,{},false
local function valid(p)return IsValid(p)and p:IsPlayer()end
function Server.Install(o)if installed then return Server end;o=o or{};profiles=assert(Profiles.new({state=o.state}));hook.Add("PlayerSpawn",Server.HookPrefix..".Spawn",function(p)timer.Simple(0,function()if valid(p)and players[p]then Server.Apply(p)end end)end);hook.Add("PlayerDisconnected",Server.HookPrefix..".Disconnect",function(p)local id=players[p];if id then profiles:disconnect(id,CurTime())end;players[p]=nil end);installed=true;return Server end
function Server.BindPlayer(p,id)if not installed or not valid(p)or type(id)~="string"then return false end;players[p]=id;return true end
function Server.HandlePut(p,rid,name,spec,revision)if not players[p]then return false,"unbound",{}end;return profiles:put(rid,players[p],name,spec,revision)end
function Server.HandleSelect(p,rid,name,revision)if not players[p]then return false,"unbound",{}end;return profiles:select(rid,players[p],name,revision)end
function Server.Apply(p)if not valid(p)or not players[p]then return false,"unbound",{}end;local plan,err=profiles:plan(players[p]);if not plan then return false,err,{}end;local ok=pcall(function()p:StripWeapons();p:RemoveAllAmmo()end);if not ok then return false,"strip_failed",{}end;local given={};for _,w in ipairs(plan.weapons)do local success,value=pcall(function()return p:Give(w.class,true)end);if not success or not IsValid(value)then return false,"give_failed",{given=given}end;given[#given+1]=w.class end;for _,a in ipairs(plan.ammo)do local success=pcall(function()p:GiveAmmo(a.amount,a.type,true)end);if not success then return false,"ammo_failed",{given=given}end end;if given[1]then p:SelectWeapon(given[1])end;return true,"applied",{weapons=given,ammo=plan.ammo}end
function Server.Save()return profiles and profiles:save(CurTime())end
function Server.Shutdown()if installed then for _,x in ipairs({{"PlayerSpawn",".Spawn"},{"PlayerDisconnected",".Disconnect"}})do hook.Remove(x[1],Server.HookPrefix..x[2])end;installed=false end;if profiles then profiles:shutdown()end;players={};return true,"shutdown"end
return Server
